package com.ruoyi.majorpilot.classifier;

import com.fasterxml.jackson.databind.*;
import java.util.*;

/** Publication-time semantic checks, not merely a checksum or generated assertion. */
public final class ClassifierAssets {
    private static final ObjectMapper JSON=new ObjectMapper();
    private ClassifierAssets(){}
    public static void validate(Map<String,byte[]> assets){try{
        JsonNode model=read(assets,"classifier-model"),practice=read(assets,"practice-public"),evaluation=read(assets,"evaluation-private"),visible=read(assets,"evaluation-public"),training=read(assets,"training-private"),golden=read(assets,"golden-private");
        fields(model,"schemaVersion labelOrder vocabulary baseCounts definitionVariants examples baselineConfig");check(model.path("schemaVersion").asText().equals("classifier-model-v1"));check(model.path("labelOrder").equals(JSON.valueToTree(FrozenClassifier.LABELS)));
        Set<String> vocabulary=new HashSet<>();check(model.path("vocabulary").isArray()&&model.path("vocabulary").size()>0&&model.path("vocabulary").size()<=4096);for(JsonNode token:model.path("vocabulary"))check(token.isTextual()&&token.asText().codePointCount(0,token.asText().length())==2&&vocabulary.add(token.asText()));
        fields(model.path("baseCounts"),String.join(" ",FrozenClassifier.LABELS));for(JsonNode row:model.path("baseCounts")){check(row.isObject()&&row.size()==vocabulary.size());for(String token:vocabulary)check(row.path(token).isIntegralNumber()&&row.path(token).asLong()>=0&&row.path(token).asLong()<=10000);}
        check(model.path("definitionVariants").size()==8);Set<String> variants=new HashSet<>();for(JsonNode variant:model.path("definitionVariants")){fields(variant,"id label title description features");check(variants.add(variant.path("id").asText())&&FrozenClassifier.LABELS.contains(variant.path("label").asText()));Set<String> unique=new HashSet<>();for(JsonNode token:variant.path("features"))check(vocabulary.contains(token.asText())&&unique.add(token.asText()));}
        Set<String> ids=new HashSet<>();for(JsonNode example:model.path("examples")){fields(example,"exampleId messageText goldLabel");check(ids.add(example.path("exampleId").asText())&&FrozenClassifier.LABELS.contains(example.path("goldLabel").asText()));}
        check(equivalent(read(assets,"example-pool"),model.path("examples")));
        check(practice.size()==24&&evaluation.size()==48&&visible.size()==48);Map<String,Map<String,Integer>> recomputed=new HashMap<>();for(String label:FrozenClassifier.LABELS){Map<String,Integer> counts=new HashMap<>();for(String token:vocabulary)counts.put(token,0);recomputed.put(label,counts);}for(JsonNode sample:training){fields(sample,"sampleId messageText goldLabel");check(ids.add(sample.path("sampleId").asText())&&FrozenClassifier.LABELS.contains(sample.path("goldLabel").asText()));var counts=recomputed.get(sample.path("goldLabel").asText());for(var entry:FrozenClassifier.features(sample.path("messageText").asText()).entrySet())if(vocabulary.contains(entry.getKey()))counts.merge(entry.getKey(),entry.getValue(),Integer::sum);}check(equivalent(JSON.valueToTree(recomputed),model.path("baseCounts")));
        int nonCorrect=0;for(JsonNode sample:practice){fields(sample,"sampleId messageText goldLabel baseline");check(ids.add(sample.path("sampleId").asText()));JsonNode prediction=FrozenClassifier.predict(model,model.path("baselineConfig"),sample.path("messageText").asText());check(equivalent(prediction,sample.path("baseline")));if(!prediction.path("routedLabel").equals(sample.path("goldLabel")))nonCorrect++;}check(nonCorrect>=8);
        Map<String,Integer> totals=new HashMap<>();for(int i=0;i<evaluation.size();i++){JsonNode secret=evaluation.get(i),pub=visible.get(i);fields(secret,"sampleId messageText goldLabel");fields(pub,"sampleId messageText");check(ids.add(secret.path("sampleId").asText())&&secret.path("sampleId").equals(pub.path("sampleId"))&&secret.path("messageText").equals(pub.path("messageText"))&&FrozenClassifier.LABELS.contains(secret.path("goldLabel").asText()));totals.merge(secret.path("goldLabel").asText(),1,Integer::sum);}for(String label:FrozenClassifier.LABELS)check(totals.get(label)==12);
        check(equivalent(FrozenClassifier.compare(model,golden.path("baselineConfig"),evaluation),golden.path("baseline")));check(equivalent(FrozenClassifier.compare(model,golden.path("changedConfig"),evaluation),golden.path("changed")));check(equivalent(read(assets,"baseline-summary"),golden.at("/baseline/baseline")));
    }catch(RuntimeException failure){throw failure;}catch(Exception failure){throw new IllegalArgumentException("CLASSIFIER_ASSETS_INVALID");}}
    public static boolean equivalent(JsonNode a,JsonNode b){if(a.isNumber()&&b.isNumber())return a.decimalValue().compareTo(b.decimalValue())==0;if(a.isObject()&&b.isObject()){if(a.size()!=b.size())return false;var fields=a.fieldNames();while(fields.hasNext()){String field=fields.next();if(!b.has(field)||!equivalent(a.get(field),b.get(field)))return false;}return true;}if(a.isArray()&&b.isArray()){if(a.size()!=b.size())return false;for(int i=0;i<a.size();i++)if(!equivalent(a.get(i),b.get(i)))return false;return true;}return a.equals(b);}
    private static JsonNode read(Map<String,byte[]> assets,String key)throws Exception {byte[] raw=assets.get(key);check(raw!=null);return JSON.readTree(raw);}
    private static void fields(JsonNode value,String fields){Set<String> expected=Set.of(fields.split(" "));check(value.isObject()&&value.size()==expected.size());for(String key:expected)check(value.has(key));}
    private static void check(boolean condition){if(!condition)throw new IllegalArgumentException("CLASSIFIER_ASSETS_INVALID");}
}
